# Aggregate panel-specific validation reports into one release gate.
root<-normalizePath(path.expand(Sys.getenv("SDY2583_REPO_ROOT",unset=getwd())),mustWork=FALSE);for(p in c("dplyr","readr","tibble","purrr","stringr"))if(!requireNamespace(p,quietly=TRUE))install.packages(p);suppressPackageStartupMessages({library(dplyr);library(readr);library(tibble);library(purrr);library(stringr)})
panels<-c("CP7","CP8","CP10","CP16","CP22","CP23","CP24","CP25","CP26","CP28");find_report<-function(panel){dir<-file.path(root,"outputs",panel,"validation");files<-if(dir.exists(dir))list.files(dir,"validation_report\\.csv$",full.names=TRUE,recursive=TRUE,ignore.case=TRUE)else character();if(!length(files))files<-if(dir.exists(dir))list.files(dir,"recovered_pipeline_validation_report\\.csv$",full.names=TRUE,recursive=TRUE,ignore.case=TRUE)else character();if(length(files))files[1]else NA_character_}
reports<-setNames(vapply(panels,find_report,character(1)),panels);summary<-purrr::imap_dfr(reports,function(path,panel){if(is.na(path)||!file.exists(path))return(tibble(panel=panel,report_file=NA_character_,n_checks=0L,n_pass=0L,n_fail=1L,all_pass=FALSE));x<-readr::read_csv(path,show_col_types=FALSE);pass_col<-c("pass","PASS")[c("pass","PASS")%in%names(x)][1];if(is.na(pass_col))return(tibble(panel=panel,report_file=path,n_checks=nrow(x),n_pass=0L,n_fail=nrow(x),all_pass=FALSE));passed<-as.logical(x[[pass_col]]);tibble(panel=panel,report_file=path,n_checks=length(passed),n_pass=sum(passed,na.rm=TRUE),n_fail=sum(!passed|is.na(passed)),all_pass=all(passed,na.rm=FALSE))})
metadata_file<-file.path(root,"data","derived","metadata","SDY2583_subject_FCS_metadata_matrix_RECONSTRUCTED.csv");integration_file<-file.path(root,"data","derived","clinical_integration","SDY2583_integrated_clinical_immune_score_matrix_ALL_PANELS_RECONSTRUCTED.csv
global_checks<-tibble(panel=c("GLOBAL_METADATA","GLOBAL_SCORE_MATRIX","SESSION_INFO"),report_file=c(metadata_file,integration_file,file.path(root,"outputs","session-info.txt")),n_checks=1L,n_pass=as.integer(file.exists(c(metadata_file,integration_file,file.path(root,"outputs","session-info.txt")))),n_fail=1L-as.integer(file.exists(c(metadata_file,integration_file,file.path(root,"outputs","session-info.txt")))),all_pass=file.exists(c(metadata_file,integration_file,file.path(root,"outputs","session-info.txt"))))
summary<-bind_rows(summary,global_checks);out<-file.path(root,"outputs","validation");dir.create(out,recursive=TRUE,showWarnings=FALSE);readr::write_csv(summary,file.path(out,"SDY2583_all_panel_validation_summary.csv"));print(summary,n=nrow(summary));if(any(!summary$all_pass))stop("All-panel validation gate failed. Review outputs/validation/SDY2583_all_panel_validation_summary.csv")
